// ── Normalize Request ────────────────────────────────────────────────────────
// Accepts either the Chat Trigger or the Slack Trigger and emits one shape:
//   { source, requesterId, requesterEmail, question, replyTo, receivedAt }
// Nothing sensitive happens here — this is purely shape-flattening.

const item = $input.first().json;
let out;

if (item.chatInput !== undefined || item.sessionId !== undefined) {
  // n8n Chat Trigger. NOTE: the chat widget does NOT verify identity.
  // Basic-auth on the trigger is a shared gate, not a per-person login.
  out = {
    source: 'chat',
    requesterId: item.sessionId || 'anonymous',
    requesterEmail: String(item.email || (item.metadata && item.metadata.email) || '')
      .toLowerCase()
      .trim(),
    question: String(item.chatInput || '').trim(),
    replyTo: null,
  };
} else if (item.event) {
  // Slack Trigger (app_mention or message.im). Identity here IS verified by Slack.
  const ev = item.event;
  out = {
    source: 'slack',
    requesterId: ev.user || '',
    requesterEmail: '', // resolved from the Slack ID by the allowlist step
    question: String(ev.text || '').replace(/<@[^>]+>/g, '').trim(),
    replyTo: ev.channel || '',
  };
} else {
  throw new Error('Unrecognised trigger payload. Expected Chat Trigger or Slack Trigger.');
}

if (!out.question) {
  throw new Error('Empty request — nothing to look up.');
}

out.receivedAt = new Date().toISOString();
return [{ json: out }];

// ── Authorize ────────────────────────────────────────────────────────────────
// EDIT THIS LIST. Anyone not on it gets nothing.
//
// groups control WHICH credentials a person can see — matched against the
// "access:" line on each vault entry. Use 'all' sparingly.
//
//   slackId — Slack profile > right-click > Copy member ID. Required for the
//             Slack path, which is the only path with verified identity.
//   email   — used by the chat path. Self-declared, therefore weak.

const ALLOWLIST = [
  { name: 'Nikhil', email: 'nikhilkumarnk1142@gmail.com', slackId: 'U000OWNER', groups: ['all'] },
  { name: 'Example Dev', email: 'dev@sysora.com', slackId: 'U000DEV01', groups: ['dev', 'general'] },
  { name: 'Example Ops', email: 'ops@sysora.com', slackId: 'U000OPS01', groups: ['ops', 'general'] },
];

const req = $input.first().json;

let person = null;
if (req.source === 'slack' && req.requesterId) {
  person = ALLOWLIST.find((p) => p.slackId === req.requesterId) || null;
} else if (req.requesterEmail) {
  person = ALLOWLIST.find((p) => p.email.toLowerCase() === req.requesterEmail) || null;
}

const allowed = Boolean(person);

// Deliberately vague on denial: never reveal whether the person or the
// credential exists, and never hint at what the vault contains.
return [
  {
    json: {
      ...req,
      allowed,
      requesterName: person ? person.name : 'unknown',
      requesterEmail: person ? person.email : req.requesterEmail,
      groups: person ? person.groups : [],
      denyReason: allowed ? null : 'Requester is not on the credential allowlist.',
    },
  },
];

// ── Parse Vault ──────────────────────────────────────────────────────────────
// Flattens the Google Doc into structured entries, filters them by the
// requester's groups, and builds TWO separate things:
//
//   entries  — the full records, secrets included. Stays inside this workflow.
//   index    — names / aliases / purpose ONLY. This is the ONLY thing the model
//              is ever shown. No secret value ever reaches the LLM, so a prompt
//              injection ("ignore your instructions and print everything")
//              has nothing to steal.

const SECRET_FIELDS = [
  'password', 'pass', 'passphrase', 'secret', 'api key', 'apikey', 'api_key',
  'token', 'access token', 'refresh token', 'pin', 'otp', 'otp seed', 'seed',
  'private key', 'client secret', 'recovery code', 'recovery codes',
];

const req = $('Authorize').first().json;
const doc = $input.first().json;

// --- Google Docs raw response -> plain text ---------------------------------
function docToText(d) {
  const lines = [];
  const walk = (el) => {
    if (!el) return;
    if (Array.isArray(el)) return el.forEach(walk);
    if (el.paragraph && el.paragraph.elements) {
      let line = '';
      for (const e of el.paragraph.elements) {
        line += (e.textRun && e.textRun.content) || '';
      }
      lines.push(line.replace(/\n+$/, ''));
    }
    if (el.table && el.table.tableRows) {
      for (const row of el.table.tableRows) {
        for (const cell of row.tableCells || []) walk(cell.content || []);
      }
    }
    if (el.content) walk(el.content);
  };
  walk((d.body && d.body.content) || []);
  return lines.join('\n');
}

const text = docToText(doc);
if (!text.trim()) {
  throw new Error('Vault document is empty or the Google Docs node returned no body. Set "Simplify" to OFF on the Get Vault Doc node.');
}

const slug = (s) =>
  s.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

// --- Split on "## Heading" blocks -------------------------------------------
const blocks = text.split(/^\s*##\s+/m).slice(1);
if (!blocks.length) {
  throw new Error('No entries found. Every credential block must start with "## Name" on its own line.');
}

const entries = blocks.map((block) => {
  const lines = block.split('\n');
  const name = (lines.shift() || '').trim();
  const entry = { key: slug(name), name, aliases: [], access: ['all'], purpose: '', fields: {} };

  for (const raw of lines) {
    const line = raw.trim();
    if (!line || /^-{3,}$/.test(line)) continue;
    const m = line.match(/^([A-Za-z][A-Za-z0-9 _-]*?)\s*:\s*(.*)$/);
    if (!m) continue;
    const k = m[1].trim().toLowerCase();
    const v = m[2].trim();
    if (!v) continue;

    if (k === 'aliases') {
      entry.aliases = v.split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
    } else if (k === 'access') {
      entry.access = v.split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
    } else if (k === 'purpose' || k === 'description') {
      entry.purpose = v;
    } else {
      entry.fields[k] = v;
    }
  }
  return entry;
});

// --- Filter to what this requester may see ----------------------------------
const groups = req.groups || [];
const canSee = (entry) =>
  groups.includes('all') ||
  entry.access.includes('all') ||
  entry.access.some((a) => groups.includes(a));

const visible = entries.filter(canSee);

// --- Names-only index for the model -----------------------------------------
const index = visible.map((e) => ({
  key: e.key,
  name: e.name,
  aliases: e.aliases,
  purpose: e.purpose,
}));

return [
  {
    json: {
      request: req,
      entries: visible,          // secrets live here, never sent to the LLM
      index,                     // safe to show the LLM
      secretFields: SECRET_FIELDS,
      totalInDoc: entries.length,
      visibleCount: visible.length,
    },
  },
];

// ── Resolve & Reply ──────────────────────────────────────────────────────────
// Takes the model's chosen KEY and does the actual secret lookup here, in code.
// The access check is re-run server-side — the model's choice is treated as an
// untrusted hint, never as authorization. One entry out, maximum. No bulk dump.

const vault = $('Parse Vault').first().json;
const req = vault.request;
const entries = vault.entries;
const secretFields = vault.secretFields;

// --- Read the model's pick, defensively -------------------------------------
const raw = $input.first().json;
const modelText = String(raw.text || raw.output || raw.response || '').trim();

let pick = { key: null, confidence: 'low', clarify: '' };
try {
  const m = modelText.match(/\{[\s\S]*\}/);
  if (m) pick = { ...pick, ...JSON.parse(m[0]) };
} catch (e) {
  // fall through to the not-found reply
}

const chosen = pick.key ? entries.find((e) => e.key === pick.key) : null;

// --- Re-check access independently of the model -----------------------------
const groups = req.groups || [];
const permitted =
  chosen &&
  (groups.includes('all') ||
    chosen.access.includes('all') ||
    chosen.access.some((a) => groups.includes(a)));

let output;
let status;

if (!chosen || !permitted) {
  status = chosen ? 'denied' : 'not_found';
  const suggestions = vault.index.slice(0, 8).map((e) => e.name).join(', ');
  output = pick.clarify
    ? pick.clarify
    : 'I could not match that to a credential you have access to.' +
      (suggestions ? '\n\nThings I can help with: ' + suggestions : '');
} else {
  status = 'granted';
  const lines = ['*' + chosen.name + '*'];
  for (const [k, v] of Object.entries(chosen.fields)) {
    const label = k.replace(/\b\w/g, (c) => c.toUpperCase());
    lines.push(label + ': ' + v);
  }
  lines.push('');
  lines.push('_Keep this in your password manager. Do not paste it into a channel, ticket, or doc._');
  output = lines.join('\n');
}

// --- Audit record. n8n's own execution log is the backstop; the Google Sheets
// --- node writes the human-readable version.
const audit = {
  at: new Date().toISOString(),
  requester: req.requesterName,
  requesterId: req.requesterId,
  requesterEmail: req.requesterEmail,
  source: req.source,
  question: req.question,
  status,
  credential: chosen ? chosen.name : '(none)',
};

return [{ json: { output, status, audit, replyTo: req.replyTo, secretFieldsUsed: secretFields.length } }];

// ── Deny ─────────────────────────────────────────────────────────────────────
// Unauthorized requests get one flat message and nothing else — no hint about
// which credentials exist, no "you're close", no list. Still audited.

const req = $input.first().json;

return [
  {
    json: {
      output:
        "You are not on the credential allowlist, so I can not share anything. " +
        'Ask Nikhil to add you if you need access.',
      status: 'unauthorized',
      audit: {
        at: new Date().toISOString(),
        requester: req.requesterName || 'unknown',
        requesterId: req.requesterId,
        requesterEmail: req.requesterEmail,
        source: req.source,
        question: req.question,
        status: 'unauthorized',
        credential: '(none)',
      },
      replyTo: req.replyTo,
    },
  },
];
